Here's a Python program that meets your requirements. This program uses a class to manage the bank account with deposit, withdrawal, and balance inquiry operations.

```python
class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            return f"Deposited ${amount}, Current Balance: ${self.balance}"
        else:
            return "Deposit amount must be positive."

    def withdrawal(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            return f"Withdrew ${amount}, Current Balance: ${self.balance}"
        elif amount > 0 and self.balance < amount:
            return f"Insufficient funds. Current Balance: ${self.balance}"
        else:
            return "Withdrawal amount must be positive."

    def balance_inquiry(self):
        return f"Current Balance: ${self.balance}"


# Example usage
account = BankAccount(1000)
print(account.balance_inquiry())  # Output: Current Balance: 1000

print(account.deposit(500))  # Output: Deposited 500, Current Balance: 1500
print(account.withdrawal(200))  # Output: Withdrew 200, Current Balance: 1300
print(account.balance_inquiry())  # Output: Current Balance: 1300
```
